"""Hand-authored release 0.13 content; run once against 0.12. YAML is authoritative."""
import json,re,copy
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
cat=json.loads((ROOT/'content/catalog.yaml').read_text())
existing={m['id']:m for m in cat['courses'][-1]['modules']}
all_new=[]
def start(key,title,obj,urls,extend=False):
 global meta,tasks,cards
 meta=(key,title,obj,urls,extend);tasks=[];cards=[]
def base(title,prompt,explain,hint):
 key,title_m,obj,urls,ext=meta;n=len(tasks)+1
 tid=f'encor.{key}.'+('ext.' if ext else '')+f'{n:02}'
 d=([2,3,3] if ext else [1,2,3])[(n-1)//6]
 common=dict(id=tid,revision=1,title=title,skills=[f'{key}.'+re.sub(r'[^a-z0-9]+','-',title.lower()).strip('-')],sources=[dict(title='Dokumentacja Cisco — '+title_m,url=u) for u in urls])
 return dict(common,blueprint_refs=[dict(exam='350-401',version='1.2',objective=obj)],difficulty=d,prompt_md=prompt,hints=[hint or explain],explanation_md=explain,card_id=tid+'.theory')
def card(t,example):
 cards.append({k:t[k] for k in ['revision','title','skills','sources']}|dict(id=t['card_id'],front_md=t['title'],back_md=t['explanation_md'],example=example));tasks.append(t)
def q(title,prompt,answer,wrong,explain,hint=''):
 t=base(title,prompt,explain,hint);n=len(tasks);pos=(n*3+n//6)%4
 opts=[]
 for w in wrong:
  text,reason=w.split('|',1);opts.append(dict(text_md=text,feedback_md=reason))
 opts.insert(pos,dict(text_md=answer,feedback_md=explain));assert len(opts)==4
 for i,o in enumerate(opts):o['id']='ABCD'[i]
 t.update(type='single_choice',options=opts,correct_option_id='ABCD'[pos]);card(t,answer)
def c(title,prompt,template,values,explain,hint=''):
 t=base(title,prompt,explain,hint);blanks=[];example=template
 for i,v in enumerate(values):
  if isinstance(v,str):a=[v];typ='command'
  else:a,typ=v
  blanks.append(dict(id=f'b{i}',label=f'Luka {i+1}',answer_type=typ,accepted=a,width=min(56,max(6,len(a[0])+2)),common_errors={}))
  example=example.replace('{{b'+str(i)+'}}',a[0])
 t.update(type='cli_fill_blank',platform='Cisco IOS / IOS XE; zgodnie z założeniami zadania',template=template,blanks=blanks);card(t,example)
def end():
 key,title,obj,urls,ext=meta;assert len(tasks)==18,(key,len(tasks))
 module=existing.get('encor.'+key) if ext else dict(id='encor.'+key,title=title,description='Od pojęć do analizy i praktycznych scenariuszy.',stages=[])
 if not ext:
  assert module['id'] not in existing
  cat['courses'][-1]['modules'].append(module)
 start_order=len(module['stages'])
 for i in range(3):
  order=start_order+i+1;sid=f'encor.{key}.stage-{order}';path=f'content/encor/{key}/stage-{order}.yaml'
  p=ROOT/path;assert not p.exists(),path;p.parent.mkdir(parents=True,exist_ok=True)
  p.write_text(json.dumps(dict(schema_version=3,id=sid,revision=1,cards=cards[i*6:i*6+6],tasks=tasks[i*6:i*6+6]),ensure_ascii=False,indent=2)+'\n')
  module['stages'].append(dict(id=sid,title=(['Rozszerzenie — zależności','Rozszerzenie — konfiguracja','Rozszerzenie — diagnostyka'] if ext else ['Podstawy','Zastosowanie','Scenariusze'])[i],description='Sześć zadań z teorią i wyjaśnieniem odpowiedzi.',difficulty=tasks[i*6]['difficulty'],order=order,pack_url='/'+path.replace('.yaml','.json'),pack_revision=1,task_count=6,pass_percent=80,requires=[] if order==1 else [f'encor.{key}.stage-{order-1}']))
 all_new.extend(tasks)


def Q(title,prompt,options,explain):
 q(title,prompt,options[0],[x+'|'+explain for x in options[1:]],explain,'Przeanalizuj warunki scenariusza; odpowiedź dotyczy wyłącznie podanych założeń.')
def C(title,prompt,template,values,explain):
 c(title,prompt,template,values,explain,'Zwróć uwagę na tryb konfiguracji i parametry wymienione w poleceniu.')
def save():
 assert len(all_new)==54,len(all_new)
 cat['revision']+=1
 (ROOT/'content/catalog.yaml').write_text(json.dumps(cat,ensure_ascii=False,indent=2)+'\n')
 print('Added',len(all_new),'ENCOR tasks')
HSRP='https://www.cisco.com/c/en/us/support/docs/ip/hot-standby-router-protocol-hsrp/13780-6.html'
HSRPC='https://www.cisco.com/c/en/us/td/docs/routers/ios/config/17-x/ntw-servs/b-network-services/m_fhp-hsrp-0.html'
VRRP='https://www.cisco.com/c/en/us/td/docs/switches/lan/c9000/lyr3-fwd/fhrp/fhrp-configuration-guide/vrrp.html'
NTP='https://www.cisco.com/c/en/us/support/docs/technical-details/220303-verify-ntp-status-with-the-show-ntp-asso.html'
NTPD='https://www.cisco.com/c/en/us/support/docs/ip/network-time-protocol-ntp/116161-trouble-ntp-00.html'
PTP='https://www.cisco.com/c/en/us/support/docs/ios-nx-os-software/ios-xr-software/217579-configure-ptp-and-synce-basics-with-cisc.html'
PBR='https://www.cisco.com/c/en/us/td/docs/routers/ios/config/17-x/ip-routing/b-ip-routing/m_iri-pbr.html'
PBRD='https://www.cisco.com/c/en/us/td/docs/routers/ios-xe/ip-routing/b-ip-routing/m_iri-pbr-default-nexthop-route.html'
start('fhrp','HSRP i VRRP — wybór bramy i awarie','3.3.c',[HSRP,HSRPC,VRRP])
Q('Adres bramy hosta','W LAN są dwa routery HSRP: 10.20.0.2 i 10.20.0.3, a VIP wynosi 10.20.0.1. Jaki adres bramy powinien dostać host?', ['10.20.0.1','10.20.0.2 jako wymóg każdego FHRP','10.20.0.3 jako wymóg każdego FHRP','Oba adresy fizyczne połączone w jeden wpis'],'Host korzysta z adresu wirtualnego. Zmiana routera obsługującego grupę nie wymaga zmiany bramy na hoście.')
Q('Rola FHRP','Który problem bezpośrednio rozwiązuje HSRP/VRRP?', ['Odporność pierwszej bramy IP w segmencie hostów','Automatyczne zapewnienie sprawności wszystkich łączy za routerem','Szyfrowanie sesji między klientami','Zastąpienie wszystkich protokołów routingu WAN'],'FHRP utrzymuje dostępność logicznej bramy. Dalsza ścieżka wymaga poprawnego routingu i odpowiedniego śledzenia awarii.')
C('Wirtualny adres HSRP','Na SVI VLAN 20 skonfiguruj grupę HSRP 20 z VIP 10.20.0.1. Adres fizyczny interfejsu już istnieje.','interface Vlan20\n standby 20 ip {{b0}}',['10.20.0.1'],'VIP musi pasować do projektu podsieci i być zgodny w tej samej grupie. Nie jest to adres fizyczny jednego routera.')
Q('Domyślny priorytet','Jakie jest domyślne priority HSRP w typowej konfiguracji IOS/IOS XE?', ['100','0','255','110'],'Domyślnie HSRP używa 100. Wyższy priorytet jest preferowany, ale przejęcie już obsadzanej roli może wymagać preempt.')
C('Wyższy priorytet','Dla grupy HSRP 20 ustaw priority 120.','interface Vlan20\n standby 20 priority {{b0}}',['120'],'Priority 120 jest wyższe od domyślnego 100. Samo priority nie jest konfiguracją preempt ani monitorowaniem uplinku.')
Q('Preempt HSRP','R1 ma priority 120, ale wraca do działającej grupy, w której R2 priority 100 jest Active. Co pozwala R1 przejąć rolę przy zachowaniu pozostałych warunków?', ['Preempt na R1','Wyłącznie zmiana hostname R1','Preempt tylko na hoście końcowym','Podniesienie numeru VLAN'],'Preempt pozwala routerowi z wyższym priorytetem odebrać rolę aktualnemu Active. Bez niego sam powrót wyższego priority nie musi zmienić roli.')
Q('Awaria Active bez preempt','Aktywny router HSRP całkowicie przestaje wysyłać Hello. Czy brak preempt na Standby uniemożliwia mu przejęcie po wygaśnięciu hold time?', ['Nie; przejęcie po utracie Active jest innym mechanizmem niż preemption','Tak, zawsze','Tak, chyba że host zmieni adres IP','Nie, ponieważ grupa zawsze miała dwóch Active'],'Preempt dotyczy wyparcia nadal aktywnego routera. Wykryta utrata Active pozwala Standby przejąć jego rolę.')
Q('Uplink padł, LAN działa','Router Active stracił wyjście WAN, lecz LAN i Hello HSRP nadal działają. Bez trackingu co może się stać?', ['Może pozostać Active mimo braku użytecznej ścieżki WAN','Musi zawsze automatycznie oddać rolę','Hosty automatycznie wykryją numer nowego AS','HSRP samo odbuduje dowolny WAN'],'FHRP nie ocenia sam wszystkich zależności usługi. Tracking może powiązać wybór bramy ze stanem istotnego łącza lub obiektu.')
C('Tracking z dekrementem','W grupie HSRP 20 śledź istniejący obiekt 7 i obniż priority o 30 po jego awarii.','interface Vlan20\n standby 20 track {{b0}} decrement {{b1}}',['7','30'],'Track odwołuje się do wcześniej utworzonego obiektu. Decrement odejmuje określoną wartość od priorytetu.')
Q('Obliczenie skutecznego priorytetu','R1: priority 120, decrement 30 dla obiektu down. R2: priority 100 i preempt. Przy sprawnym LAN który router ma wyższy skuteczny priorytet?', ['R2: 100 wobec 90 na R1','R1: 120 wobec 100 na R2','R1: 150 wobec 100 na R2','Remis 100 do 100'],'Po spadku obiektu R1 ma 120 − 30 = 90. R2 z preempt może przejąć rolę przy spełnieniu pozostałych warunków.')
C('VRRP IPv4 — klasyczna składnia','Na platformie wspierającej klasyczną interfejsową składnię VRRP IPv4 ustaw grupę 30, VIP 10.30.0.1 i priority 110. Adres fizyczny już istnieje.','interface Vlan30\n vrrp 30 ip {{b0}}\n vrrp 30 priority {{b1}}',['10.30.0.1','110'],'Polecenia dotyczą wskazanej klasycznej składni. Nowsza składnia address-family VRRPv3 wymaga osobnego kontekstu i nie jest tu używana.')
Q('Właściciel adresu VRRP','Router VRRP jest właścicielem adresu IP używanego jako VIP. Jaki specjalny priorytet jest z tym związany?', ['255','100','0','1'],'Właściciel adresu ma szczególny status i priority 255. Nie należy utożsamiać tej wartości z domyślnym priorytetem zwykłego uczestnika.')
Q('Za mały decrement','R1 Active ma priority 130 i decrement 10. R2 ma 110 i preempt. Track R1 przechodzi down. Dlaczego R2 nie musi przejąć?', ['R1 nadal ma 120, czyli więcej niż 110','Tracking zawsze zeruje priority','Preempt działa tylko przy identycznych priorytetach','R2 musi zmienić VIP'],'Decrement musi być dobrany do różnicy priorytetów. Sam fakt skonfigurowania trackingu nie gwarantuje zmiany preferencji.')
Q('Dwie grupy, dwa aktywne routery','R1 jest Active grupy 10, R2 Active grupy 20. Hosty mają różne VIP-y według projektu. Jaka korzyść jest możliwa?', ['Podział obciążenia między grupami przy zachowaniu redundancji każdej grupy','Automatyczny per-packet load balancing jednego VIP przez dwa Active HSRP','Usunięcie potrzeby routingu między VLAN-ami','Zamiana HSRP w LACP'],'Różne grupy mogą preferować różne routery. Nie oznacza to dwóch równoczesnych Active dla jednej zwykłej grupy HSRP.')
C('Pełny wybór preferowanej bramy','VLAN 40 ma fizyczny adres R1 10.40.0.2/24. Ustaw HSRP 40: VIP 10.40.0.1, priority 120, preempt.','interface Vlan40\n standby 40 ip {{b0}}\n standby 40 priority {{b1}}\n standby 40 {{b2}}',['10.40.0.1','120','preempt'],'VIP, priorytet i preemption pełnią różne role. Drugi router musi mieć zgodne parametry grupy i odrębny adres fizyczny.')
Q('Oba routery zgłaszają Active','Na tym samym planowanym LAN oba routery HSRP zgłaszają Active dla tej samej grupy. Co jest istotnym kierunkiem diagnozy?', ['Wzajemna widoczność Hello, VLAN, wersja i zgodność parametrów grupy','Wyłącznie zwiększenie priorytetów obu routerów','Wyłącznie zmiana DNS hostów','Uznanie tego za zwykły wymagany stan HSRP'],'Brak komunikacji lub niezgodność może rozdzielić postrzeganie grupy. Sprawdź L2 i parametry protokołu przed zmianą priorytetów.')
C('VRRP z kontrolą preferencji','Na platformie obsługującej klasyczne VRRP IPv4 ustaw na VLAN 50: grupę 50, VIP 10.50.0.1, priority 120 i jawnie preempt.','interface Vlan50\n vrrp 50 ip {{b0}}\n vrrp 50 priority {{b1}}\n vrrp 50 {{b2}}',['10.50.0.1','120','preempt'],'Jawna konfiguracja pokazuje zamierzony wybór routera. Nie przenoś bez sprawdzenia składni i domyślnych zachowań między HSRP oraz wersjami VRRP.')
Q('Próg i opóźnienie powrotu','Router wrócił do LAN, ale jego routing WAN jeszcze się zbiega. Po co stosować odpowiednie opóźnienie preempt?', ['Aby nie przejął bramy przed gotowością dalszej ścieżki','Aby wyłączyć wszystkie Hello na stałe','Aby zmienić adres VIP na fizyczny','Aby zagwarantować szyfrowanie FHRP'],'Natychmiastowe odzyskanie roli nie zawsze jest korzystne. Opóźnienie powinno uwzględniać czas stabilizacji usług i routingu.')
end()
start('time-sync','NTP i PTP — interpretacja synchronizacji','3.3.a',[NTP,NTPD,PTP])
Q('Cel NTP','Dlaczego spójny czas urządzeń pomaga w diagnozie incydentu sieciowego?', ['Pozwala wiarygodniej porównywać kolejność zdarzeń w logach','Automatycznie naprawia wszystkie błędy routingu','Zastępuje identyfikator sesji TCP','Wymusza ten sam adres IP na routerach'],'Bez spójnego czasu korelacja logów z różnych urządzeń może prowadzić do błędnych wniosków o kolejności zdarzeń.')
Q('Transport NTP','Jaki port UDP jest standardowo związany z usługą NTP?', ['123','161','179','830'],'NTP używa UDP 123. Pozostałe wartości wiążą się z innymi usługami i nie potwierdzają dostępu do czasu.')
Q('Znaczenie stratum','Co opisuje stratum w NTP?', ['Logiczną odległość w hierarchii synchronizacji od źródła odniesienia','Liczbę fizycznych skoków IP w traceroute','Opóźnienie zawsze wyrażone w milisekundach','Numer wersji TLS'],'Stratum jest poziomem hierarchii czasu. Nie jest bezpośrednim pomiarem dokładności ani liczbą routerów na ścieżce.')
Q('Brak synchronizacji','Wynik show ntp status wskazuje stratum 16 i brak synchronizacji. Co to oznacza?', ['Zegar nie jest zsynchronizowany jako użyteczne źródło NTP','Dokładnie szesnaście poprawnych serwerów','Najwyższą możliwą precyzję zegara','Szesnaście milisekund opóźnienia'],'Stratum 16 oznacza stan niesynchronizowany. Sama obecność konfiguracji serwera nie dowodzi działającej synchronizacji.')
Q('Odczyt ntp server','Co deklaruje konfiguracja ntp server 192.0.2.10?', ['Urządzenie ma używać wskazanego serwera jako źródła NTP','Urządzenie musi mieć lokalny adres 192.0.2.10','Każdy host automatycznie dostaje ten adres przez DHCP','Polecenie ustawia lokalną strefę czasową'],'To konfiguracja relacji ze źródłem czasu. Trzeba jeszcze sprawdzić osiągalność i wyniki wyboru/synchronizacji.')
Q('Strefa czasowa','Dwa zsynchronizowane routery pokazują różne lokalne godziny przez różne clock timezone. Jaki wniosek jest uzasadniony?', ['Różna prezentacja lokalna nie musi oznaczać rozbieżności czasu UTC','NTP musi być całkowicie niesprawne','Każda strefa czasowa wymaga osobnego protokołu','Zegar drugiego routera zawsze wymaga ręcznego cofnięcia'],'Strefa wpływa na prezentację czasu. Porównuj właściwy punkt odniesienia oraz znacznik strefy, a nie tylko samą godzinę.')
Q('Wybrane źródło','W typowym show ntp associations przy adresie źródła widnieje *. Co oznacza ta flaga według legendy polecenia?', ['Wybrane źródło synchronizacji systemu','Dowolny skonfigurowany serwer, zawsze niesprawny','Adres wykluczony z wyboru','Brak odpowiedzi od ostatnich ośmiu prób'],'Gwiazdka identyfikuje system peer. Inne oznaczenia, np. samo ~, mogą dotyczyć konfiguracji, a nie wyboru.')
Q('Reach 377','Pole reach w show ntp associations ma 377. Jak je interpretować?', ['Ósemkowa maska wskazująca sukces ostatnich ośmiu prób','377 milisekund opóźnienia','377 odebranych pakietów od restartu','Liczba sekund do zmiany serwera'],'Reach jest rejestrem bitowym prezentowanym ósemkowo. 377 octal odpowiada ośmiu jedynkom, a nie licznikowi czasu.')
Q('Reach 0','Nowa asocjacja przez dłuższy czas ma reach 0. Co warto sprawdzić?', ['Osiągalność, UDP 123, ACL, źródło zapytań i odpowiedzi serwera','Wyłącznie zwiększyć lokalną strefę o godzinę','Wyłącznie zmienić opis interfejsu','Uznać pewną pełną synchronizację'],'Brak udanych prób wymaga diagnozy ścieżki i parametrów. Pojedynczy odczyt tuż po starcie nie wystarcza do oceny trwałej awarii.')
Q('Jawne źródło NTP','Konfiguracja zawiera ntp source Loopback0. Co trzeba uwzględnić po stronie serwera i sieci?', ['Osiągalność powrotną oraz ACL dla adresu Loopback0','Wyłącznie adres fizyczny interfejsu WAN','NTP zawsze ignoruje polecenie source','Loopback musi należeć do VLAN 1'],'Jawne źródło zmienia adres używany przez klienta. Trasa powrotna i dozwolone źródła muszą odpowiadać temu wyborowi.')
Q('Lokalny master','Dlaczego ntp master nie jest dowodem, że router zna poprawny czas UTC?', ['Może udostępniać lokalny zegar bez wiarygodnego zewnętrznego odniesienia','Zawsze łączy się automatycznie z GPS','Zawsze pobiera czas z DNS','Każdy master ma gwarantowaną dokładność atomową'],'Lokalne źródło może pomóc zachować wspólny czas w odciętej sieci, ale samo nie zapewnia poprawności względem UTC.')
Q('Prefer nie naprawia źródła','Serwer oznaczono prefer, ale dostarcza niewiarygodne lub nieprawidłowe dane. Czy prefer gwarantuje jego bezwarunkowy wybór?', ['Nie; nadal obowiązują mechanizmy sprawdzania i wyboru źródeł','Tak, prefer wyłącza każdą kontrolę NTP','Tak, prefer zastępuje uwierzytelnienie','Nie, bo prefer dotyczy wyłącznie strefy czasu'],'Prefer wpływa na preferencję wśród odpowiednich źródeł. Nie powinien być traktowany jako obejście wszystkich warunków synchronizacji.')
Q('PTP grandmaster','Jaką rolę ma grandmaster w domenie PTP?', ['Głównego źródła czasu dla tej domeny','Wyłącznie kolektora logów NTP','Routera wybierającego trasy BGP','Zawsze transparent clock bez własnego odniesienia'],'Grandmaster jest odniesieniem dla hierarchii PTP. Wybór i własności źródła zależą od profilu i konfiguracji.')
Q('Boundary clock','Co robi boundary clock PTP w typowej hierarchii?', ['Synchronizuje się do źródła upstream i dostarcza czas dalej przez inne porty PTP','Tylko kopiuje pakiety bez udziału zegara','Zawsze konwertuje PTP na routing statyczny','Działa wyłącznie jako odbiorca bez portów downstream'],'Boundary clock uczestniczy w synchronizacji i tworzy kolejne relacje na swoich portach. Nie jest tylko zwykłym mostem.')
Q('Transparent clock','Jaki jest istotny cel transparent clock PTP?', ['Uwzględnianie czasu przebywania komunikatu w urządzeniu w odpowiedniej korekcji','Zastąpienie każdego grandmastera bez wyboru','Usuwanie całego nagłówka Ethernet','Zmiana UDP 123 na SSH 830'],'Transparent clock pomaga kompensować opóźnienie przejścia. Szczegóły korekcji zależą m.in. od trybu i profilu PTP.')
Q('Domena i profil PTP','Dwa urządzenia są osiągalne IP, ale używają niezgodnych domen/profili PTP. Co może wyjaśniać brak wspólnej synchronizacji?', ['Osiągalność IP nie zapewnia zgodności parametrów protokołu czasu','Każdy ping automatycznie uzgadnia profil PTP','Wystarczy zmienić strefę czasową Windows','PTP nie korzysta z żadnego kontekstu domeny'],'Do współpracy potrzeba zgodnego projektu domeny, profilu, transportu i mechanizmu opóźnienia. Sam routing to za mało.')
Q('Asymetria ścieżki','Dlaczego różne opóźnienia w dwóch kierunkach mogą pogarszać estymację czasu?', ['Mechanizm wyznaczania offsetu może opierać się na założeniu lub kompensacji symetrii','Stratum zawsze staje się numerem VLAN','Każdy pakiet traci adres MAC','NTP i PTP mierzą tylko przepustowość'],'Asymetria może wprowadzać błąd w szacowaniu czasu. Projekt precyzyjnej synchronizacji uwzględnia ścieżkę i możliwości sprzętu.')
Q('Nie gwarantuj precyzji z nazwy','Firma uruchomiła PTP na przypadkowej sieci bez weryfikacji timestampingu i profilu. Czy sama nazwa PTP gwarantuje dokładność submikrosekundową?', ['Nie; wynik zależy od sprzętu, profilu, topologii, opóźnień i źródła','Tak, na każdym urządzeniu i przy dowolnym obciążeniu','Tak, jeśli serwer ma niski adres IP','Nie, ponieważ PTP nigdy nie może być precyzyjniejsze od zegara ręcznego'],'PTP umożliwia precyzyjne projekty, ale konkretny poziom dokładności wymaga zgodnego wdrożenia i pomiaru.')
end()
start('pbr','PBR — interpretacja polityk routingu','3.2.d',[PBR,PBRD])
Q('Cel PBR','Co umożliwia policy-based routing poza zwykłym wyborem trasy według adresu docelowego?', ['Wybór drogi według zdefiniowanych kryteriów, np. źródła lub rodzaju ruchu','Automatyczne szyfrowanie każdego pakietu','Zastąpienie ARP przez BGP','Wyłącznie zmianę numeru VLAN'],'PBR pozwala stosować politykę do wybranych pakietów. Nie oznacza rezygnacji z routingu i osiągalności next hopów.')
Q('Route-map jako polityka','Jaką rolę pełni route-map w typowym PBR IOS XE?', ['Łączy kryteria match z akcjami set dla dopasowanego ruchu','Zawsze rozgłasza prefiksy przez BGP niezależnie od zastosowania','Wyłącznie przechowuje hasła lokalnych użytkowników','Jest odpowiednikiem tablicy MAC'],'Route-map jest mechanizmem używanym w różnych funkcjach. Znaczenie permit/deny i set trzeba rozpatrywać w kontekście PBR.')
Q('Punkt zastosowania','Na LAN Gi0/0 widnieje ip policy route-map USER-PBR. Jakiego kierunku typowo dotyczy ta polityka interfejsowa?', ['Pakietów wpływających przez Gi0/0','Wyłącznie pakietów wychodzących przez Gi0/0','Wyłącznie pakietów generowanych lokalnie przez CPU','Wszystkich pakietów na każdym interfejsie bez wyjątku'],'Interfejsowy PBR stosuje się na wejściu ruchu do routera. To nie jest zwykła polityka wyjściowa kolejki.')
Q('Next hop w PBR','Co określa set ip next-hop 192.0.2.2 w dopasowanej sekwencji permit?', ['Preferowany przez tę akcję next hop dla podlegających polityce pakietów','Adres źródłowy pakietów po NAT','Adres nowego serwera DNS','Nowy router ID OSPF'],'Akcja wpływa na forwarding. Nie zmienia automatycznie adresów pakietów jak translacja NAT.')
Q('ACL w match','ACL użyto w match ip address, nie jako ip access-group. Wpis ACL deny oznacza w tej roli:', ['Brak dopasowania do tego warunku polityki','Bezwarunkowe odrzucenie pakietu jak ACL filtrująca na interfejsie','Wymuszenie wysłania pakietu do każdego next hop','Automatyczne usunięcie trasy statycznej'],'ACL klasyfikuje ruch dla route-map. Dalsze postępowanie zależy od kolejnych sekwencji i zasad PBR.')
Q('Brak dopasowania','Pakiet nie pasuje do żadnej sekwencji route-map użytej jako PBR. Jak zwykle jest obsługiwany?', ['Przez normalny routing według dostępnej tablicy','Zawsze odrzucany tylko z powodu implicit deny route-map','Automatycznie NAT-owany','Wysyłany na wszystkie porty'],'W PBR brak dopasowania nie oznacza automatycznie drop. Nie przenoś bezpośrednio semantyki filtrowania tras lub ACL do tej funkcji.')
Q('Route-map deny','Pakiet dopasował sekwencję route-map deny w PBR. Jak należy interpretować ten wynik?', ['Nie stosuj akcji PBR dla tego pakietu; korzystaj z normalnego routingu','Odrzuć go bezwarunkowo niezależnie od routingu','Zastosuj wszystkie set z kolejnych sekwencji','Zaszyfruj go przed lookup'],'Deny w kontekście PBR wyłącza policy routing dla pasującego ruchu. Zwykły routing nadal może przekazać lub odrzucić pakiet według swoich warunków.')
Q('Wybór według źródła','Firma chce wysyłać ruch z 10.10.0.0/24 przez ISP-A, a z 10.20.0.0/24 przez ISP-B do tych samych celów. Który mechanizm odpowiada temu wymaganiu?', ['PBR z klasyfikacją źródeł i właściwymi next hopami','Sama jedna trasa domyślna bez dodatkowej polityki','Wyłącznie zmiana router ID','Wyłącznie jedna reguła DNS'],'PBR może różnicować ruch do tego samego celu według źródła. Projekt wymaga także routingu powrotnego i ewentualnego NAT.')
Q('Dwie sekwencje','Route-map ma permit 10 dla source 10.10.0.0/24 i permit 20 dla szerszego 10.0.0.0/8. Pakiet z 10.10.0.5 spełnia oba kryteria. Która sekwencja jest rozpatrywana jako pierwsza?', ['10','20','Obie zawsze wykonują wszystkie akcje','Ta, której nazwa ma więcej znaków'],'Sekwencje są rozpatrywane według numeracji. Zbyt szeroka reguła umieszczona wcześniej może przesłonić bardziej szczegółowy zamiar.')
Q('Set next-hop a default next-hop','Jaką różnicę trzeba uwzględnić między set ip next-hop a set ip default next-hop?', ['Default next-hop jest używany w kontekście braku odpowiedniej jawnej trasy; kolejność względem normalnego lookup jest inna','Oba zawsze oznaczają dokładnie tę samą kolejność wyboru','Default next-hop zmienia adres źródłowy','Set next-hop służy wyłącznie do OSPF'],'To różne akcje. Szczegółowe traktowanie default route i wsparcie sprzętowe należy sprawdzić na platformie, zamiast utożsamiać obie składnie.')
Q('Polityka dla ruchu lokalnego','Operator pinguje z samego routera, ale test nie podlega ip policy na interfejsie LAN. Dlaczego?', ['Ruch lokalnie wygenerowany nie wpłynął przez ten interfejs; local PBR jest osobnym mechanizmem','Ping nigdy nie może podlegać żadnej polityce','Każda route-map działa tylko na TCP','Adres docelowy musi być adresem MAC'],'Interfejsowy PBR dotyczy ruchu przychodzącego. Test z hosta za LAN i test z routera nie są równoważne.')
Q('Polityka istnieje bez przypięcia','Running-config zawiera route-map USER-PBR, ale żaden właściwy interfejs nie ma ip policy route-map USER-PBR. Co wynika z tego dla ruchu tranzytowego?', ['Sama definicja nie stosuje jeszcze tej polityki na wejściu interfejsu','Route-map automatycznie obejmuje wszystkie porty','Route-map działa wyłącznie dzięki swojej nazwie','Każdy pakiet jest odrzucany do czasu usunięcia definicji'],'Definicja obiektu i jego zastosowanie to oddzielne kroki. Sprawdź punkt wejścia rzeczywistego ruchu.')
Q('Awaria za next hopem','Next hop PBR odpowiada i jest lokalnie osiągalny, ale jego dalsze łącze operatora nie działa. Dlaczego prosty set ip next-hop może nie wystarczyć?', ['Lokalna osiągalność next hopu nie dowodzi dostępności całej usługi; może być potrzebne właściwe śledzenie','PBR zawsze testuje dowolny serwer końcowy automatycznie','Router musi zmienić port TCP aplikacji','Każda awaria operatora automatycznie usuwa interfejs LAN'],'Dobre śledzenie powinno odpowiadać faktycznej zależności. Sam sąsiad może działać mimo utraty dalszej ścieżki.')
Q('Ruch powrotny','PBR kieruje zapytania przez ISP-B, ale odpowiedzi wracają przez ISP-A z firewall stateful. Jakie ryzyko trzeba ocenić?', ['Asymetrię ścieżek i zgodność stanu/NAT/polityk','Wyłącznie zmianę czasu NTP','Wyłącznie większą liczbę wpisów CDP','Brak jakichkolwiek konsekwencji dla urządzeń stanowych'],'PBR steruje daną drogą ruchu, a nie automatycznie drogą powrotną. Asymetria może kolidować z NAT lub kontrolą stanową.')
Q('Analiza konkretnego pakietu','Skrócona polityka dydaktyczna:\n```text\nip access-list extended TO-ISP-B\n permit ip 10.20.0.0 0.0.0.255 any\nroute-map USER-PBR permit 10\n match ip address TO-ISP-B\n set ip next-hop 192.0.2.2\n```\nPolityka jest przypięta na wejściu LAN, next hop jest dostępny. Co dotyczy pakietu z 10.20.0.7 do 203.0.113.8?', ['Pasuje do ACL i kwalifikuje się do akcji next hop 192.0.2.2','Nie pasuje, bo ACL wymaga celu 10.20.0.0/24','Musi zostać odrzucony przez permit','Automatycznie zmieni source na 192.0.2.2'],'Pierwszy prefiks ACL opisuje źródło, a any — dowolny cel. Akcja next-hop nie jest translacją źródła.')
Q('Pakiet spoza polityki','Ta sama ACL TO-ISP-B dopuszcza tylko source 10.20.0.0/24. Nie ma dalszych sekwencji. Pakiet z 10.30.0.7 wpływa tym samym interfejsem. Co nastąpi w typowym PBR?', ['Normalny routing, ponieważ pakiet nie pasuje do polityki','Zawsze odrzucenie przez samo implicit deny klasyfikatora','Wymuszenie next hop 192.0.2.2 dla każdego źródła','Zmiana źródła na 10.20.0.7'],'Niedopasowanie kończy się zwykłym lookup. To, czy pakiet zostanie potem przekazany, zależy od tras i innych polityk.')
Q('Weryfikacja działania','Po wdrożeniu PBR ruch nadal idzie starą drogą. Który zestaw sprawdzeń najlepiej odpowiada problemowi?', ['Przypięcie na właściwym wejściu, liczniki match, rzeczywiste pola pakietu i dostępność next hopu','Wyłącznie numer sekwencji ACL bez sprawdzania ruchu','Wyłącznie zapis startup-config','Wyłącznie zmiana nazwy route-map'],'Sprawdź cały łańcuch: punkt zastosowania, klasyfikację, akcję i forwarding. Samo istnienie konfiguracji nie potwierdza trafień.')
Q('Granice prostego PBR','Czy sam source-based PBR automatycznie wybiera łącze o najmniejszym jitter dla konkretnej aplikacji?', ['Nie; wymagałoby to dodatkowych pomiarów i logiki/polityki','Tak, każda route-map ma wbudowane pomiary SLA aplikacji','Tak, bo ACL mierzy jitter każdego pakietu','Nie, ponieważ PBR nie może używać żadnych warunków'],'Prosta klasyfikacja i next-hop nie są pełnym application-aware routing. Należy rozróżniać zakres mechanizmów.')
end()
save()
